def rightmost_per_level(root: "TreeNode | None") -> list[int]:
    view = []
    level = [root] if root else []
    while level:
        view.append(level[-1].val)       # levels are built left to right
        level = [child for node in level for child in (node.left, node.right) if child]
    return view


